'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var floor = require( '@stdlib/math/base/special/floor' );
var gindexOfGreaterThanEqual = require( '@stdlib/blas/ext/base/gindex-of-greater-than-equal' ).ndarray;


// MAIN //

/**
* Returns the index of the first element in a sorted double-precision floating-point strided array which is greater than or equal to a specified search element using alternative indexing semantics.
*
* ## Notes
*
* -   If unable to find an element which is greater than or equal to the search element, the function returns `-1`.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {number} searchElement - search element
* @param {Float64Array} x - sorted input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {integer} index
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = dindexOfGreaterThanEqualSorted( x.length, 2.0, x, 1, 0 );
* // returns 1
*/
function dindexOfGreaterThanEqualSorted( N, searchElement, x, strideX, offsetX ) {
	var idx;
	var mid;
	var ix;
	var lo;
	var hi;
	var v1;
	var v2;
	var v;

	if ( N <= 0 ) {
		return -1;
	}
	v1 = x[ offsetX ];
	v2 = x[ offsetX + ( ( N - 1 ) * strideX ) ];

	// If either the first or last indexed element is NaN, we cannot determine the sort order, so fall back to a linear search...
	if ( isnan( v1 ) || isnan( v2 ) ) {
		return gindexOfGreaterThanEqual( N, searchElement, x, strideX, offsetX ); // eslint-disable-line max-len
	}
	// Descending order: elements which are greater than or equal to the search element form a prefix, so only the first indexed element needs to be checked...
	if ( v1 >= v2 ) {
		if ( searchElement <= v1 ) {
			return 0;
		}
		return -1;
	}
	// Ascending order: perform a binary search for the first element which is greater than or equal to the search element...
	lo = 0;
	hi = N;
	while ( lo < hi ) {
		mid = lo + floor( ( hi - lo ) / 2 );
		v = x[ offsetX + ( mid * strideX ) ];

		// If we encounter a NaN, fall back to a linear search...
		if ( isnan( v ) ) {
			ix = offsetX + ( lo * strideX );
			idx = gindexOfGreaterThanEqual( N-lo, searchElement, x, strideX, ix ); // eslint-disable-line max-len
			return ( idx < 0 ) ? idx : idx + lo;
		}
		if ( searchElement <= v ) {
			hi = mid;
		} else {
			lo = mid + 1;
		}
	}
	if ( lo === N ) {
		return -1;
	}
	return lo;
}


// EXPORTS //

module.exports = dindexOfGreaterThanEqualSorted;
